INSERT INTO cursos (id, titulo, area, nivel, duracion_semanas, modalidad, fase, docente_id, instructor, edad_minima, descripcion, objetivo, temario, modulos, guia, proyecto) VALUES (1, 'HTML y CSS: tu primera página web', 'Software', 'Básico', 2, 'Presencial', 'Lanzamiento', (SELECT id FROM usuarios WHERE nombre = 'Por asignar' AND rol = 'docente'), 'Por asignar', 14, 'El punto de partida de la ruta. Aprendes cómo está hecha una página web, escribes su estructura con HTML y le das estilo con CSS hasta que se vea bien en el celular y en el computador. No necesitas saber nada de programación.', 'Construir y publicar una página web sencilla, ordenada y que se vea bien en cualquier pantalla.', ARRAY['La web y HTML: Cómo funciona una página web, etiquetas y estructura, títulos, párrafos, enlaces e imágenes', 'CSS: color y tipografía: Selectores, colores y fuentes, el modelo de caja', 'Diseño que se adapta: Flexbox, diseño responsive, imágenes que se ajustan', 'Publica tu página: Formularios básicos, revisión final, publicar con GitHub Pages']::text[], '[{"titulo":"La web y HTML","temas":["Cómo funciona una página web","Etiquetas y estructura","Títulos, párrafos, enlaces e imágenes"],"temasTexto":"Cómo funciona una página web, etiquetas y estructura, títulos, párrafos, enlaces e imágenes","actividades":["Escribir la estructura de una página sobre ti con títulos, párrafos, una imagen y enlaces."],"evidencia":"Archivo index.html con la estructura completa de tu página."},{"titulo":"CSS: color y tipografía","temas":["Selectores","Colores y fuentes","El modelo de caja"],"temasTexto":"Selectores, colores y fuentes, el modelo de caja","actividades":["Darle a tu página una paleta de colores, tipografías y espacios propios."],"evidencia":"Hoja de estilos conectada a tu página."},{"titulo":"Diseño que se adapta","temas":["Flexbox","Diseño responsive","Imágenes que se ajustan"],"temasTexto":"Flexbox, diseño responsive, imágenes que se ajustan","actividades":["Organizar la página en secciones y hacer que se vea bien en el celular y en el computador."],"evidencia":"Página que funciona en celular y computador."},{"titulo":"Publica tu página","temas":["Formularios básicos","Revisión final","Publicar con GitHub Pages"],"temasTexto":"Formularios básicos, revisión final, publicar con GitHub Pages","actividades":["Agregar un formulario de contacto, pulir los detalles y publicar la página en internet."],"evidencia":"Enlace público de tu página."}]'::jsonb, '{"modalidad":"Clase presencial en Barranquilla: explica con un ejemplo en pantalla, deja que cada estudiante lo repita en su computador y cierra mostrando el avance de dos o tres personas.","nota":"","reto":"Agrega una sección nueva a tu página y comprueba que se siga viendo bien en un celular.","preguntas":["¿Qué ve primero la persona que entra a tu página?","¿Cómo se ve en una pantalla pequeña?","¿Cómo lo comprobarías?"]}'::jsonb, 'Tu página personal o la de un negocio de tu barrio, publicada en internet.');
INSERT INTO cursos (id, titulo, area, nivel, duracion_semanas, modalidad, fase, docente_id, instructor, edad_minima, descripcion, objetivo, temario, modulos, guia, proyecto) VALUES (2, 'JavaScript para principiantes', 'Software', 'Básico', 2, 'Presencial', 'Lanzamiento', (SELECT id FROM usuarios WHERE nombre = 'Por asignar' AND rol = 'docente'), 'Por asignar', 14, 'Le das vida a tu página: botones que responden, contenido que cambia y formularios que revisan lo que escribe la persona. Aprendes las bases de la programación usando la página que construiste en el curso anterior.', 'Programar la interacción de una página web con JavaScript.', ARRAY['Primeros pasos en JavaScript: Variables y tipos de datos, operadores, la consola del navegador', 'Decisiones, ciclos y funciones: Condicionales, ciclos, funciones', 'El DOM y los eventos: Seleccionar elementos, cambiar contenido y estilos, clics y eventos', 'Formularios y datos: Validar formularios, arreglos y objetos, guardar en el navegador']::text[], '[{"titulo":"Primeros pasos en JavaScript","temas":["Variables y tipos de datos","Operadores","La consola del navegador"],"temasTexto":"Variables y tipos de datos, operadores, la consola del navegador","actividades":["Resolver retos cortos en la consola: calcular, comparar y mostrar mensajes."],"evidencia":"Archivo con los retos resueltos y comentados."},{"titulo":"Decisiones, ciclos y funciones","temas":["Condicionales","Ciclos","Funciones"],"temasTexto":"Condicionales, ciclos, funciones","actividades":["Crear una calculadora de descuentos para una tienda del barrio."],"evidencia":"Calculadora funcionando en el navegador."},{"titulo":"El DOM y los eventos","temas":["Seleccionar elementos","Cambiar contenido y estilos","Clics y eventos"],"temasTexto":"Seleccionar elementos, cambiar contenido y estilos, clics y eventos","actividades":["Agregar a tu página un menú que se abre en el celular y un botón de modo oscuro."],"evidencia":"Tu página con interacción."},{"titulo":"Formularios y datos","temas":["Validar formularios","Arreglos y objetos","Guardar en el navegador"],"temasTexto":"Validar formularios, arreglos y objetos, guardar en el navegador","actividades":["Validar el formulario de contacto y mostrar una lista que se puede filtrar."],"evidencia":"Enlace público de tu página con JavaScript."}]'::jsonb, '{"modalidad":"Clase presencial en Barranquilla: programa en vivo pensando en voz alta, deja que cada estudiante lo repita y revisen juntos los errores de la consola.","nota":"","reto":"Agrega un botón nuevo que cambie algo de la página y explica qué pasa paso a paso.","preguntas":["¿Qué pasa cuando la persona hace clic?","¿Qué pasa si escribe algo que no esperabas?","¿Cómo lo comprobarías en la consola?"]}'::jsonb, 'Tu página del curso anterior con un menú, un modo oscuro y un formulario que valida los datos.');
INSERT INTO cursos (id, titulo, area, nivel, duracion_semanas, modalidad, fase, docente_id, instructor, edad_minima, descripcion, objetivo, temario, modulos, guia, proyecto) VALUES (3, 'Python desde cero', 'Software', 'Básico', 2, 'Presencial', 'Lanzamiento', (SELECT id FROM usuarios WHERE nombre = 'Por asignar' AND rol = 'docente'), 'Por asignar', 14, 'Pasas al otro lado de la web: el servidor. Aprendes Python, uno de los lenguajes más fáciles de leer, y lo usas para crear el programa que recibe y responde lo que envía tu página.', 'Escribir programas en Python y crear un servidor web sencillo que se comunique con tu página.', ARRAY['Python básico: Variables y tipos de datos, entrada y salida, condicionales', 'Listas, ciclos y funciones: Listas y diccionarios, ciclos, funciones', 'Tu primer servidor web: Qué es un servidor, Flask, rutas y plantillas', 'Conecta tu página: Recibir datos de un formulario, responder en JSON, fetch desde JavaScript']::text[], '[{"titulo":"Python básico","temas":["Variables y tipos de datos","Entrada y salida","Condicionales"],"temasTexto":"Variables y tipos de datos, entrada y salida, condicionales","actividades":["Hacer un programa que pregunte datos y responda según lo que escribe la persona."],"evidencia":"Archivo .py con el programa funcionando."},{"titulo":"Listas, ciclos y funciones","temas":["Listas y diccionarios","Ciclos","Funciones"],"temasTexto":"Listas y diccionarios, ciclos, funciones","actividades":["Programar el inventario de una tienda: agregar, buscar y sumar productos."],"evidencia":"Programa del inventario con sus funciones."},{"titulo":"Tu primer servidor web","temas":["Qué es un servidor","Flask","Rutas y plantillas"],"temasTexto":"Qué es un servidor, Flask, rutas y plantillas","actividades":["Crear con Flask una página que muestre los productos del inventario."],"evidencia":"Servidor Flask que responde en el navegador."},{"titulo":"Conecta tu página","temas":["Recibir datos de un formulario","Responder en JSON","fetch desde JavaScript"],"temasTexto":"Recibir datos de un formulario, responder en JSON, fetch desde JavaScript","actividades":["Hacer que el formulario de tu página envíe los mensajes a tu servidor en Python."],"evidencia":"Tu página enviando datos a tu servidor."}]'::jsonb, '{"modalidad":"Clase presencial en Barranquilla: muestra cada idea con un ejemplo corto, deja que lo cambien y lo ejecuten, y cierra conectándolo con la página que ya tienen.","nota":"","reto":"Agrega una ruta nueva a tu servidor y llámala desde tu página.","preguntas":["¿Qué recibe tu programa?","¿Qué devuelve?","¿Qué pasa si llega un dato vacío?"]}'::jsonb, 'Un servidor hecho con Flask que recibe los mensajes del formulario de tu página.');
INSERT INTO cursos (id, titulo, area, nivel, duracion_semanas, modalidad, fase, docente_id, instructor, edad_minima, descripcion, objetivo, temario, modulos, guia, proyecto) VALUES (4, 'PostgreSQL: tu primera base de datos', 'Software', 'Intermedio', 2, 'Presencial', 'Lanzamiento', (SELECT id FROM usuarios WHERE nombre = 'Por asignar' AND rol = 'docente'), 'Por asignar', 14, 'La última pieza: guardar la información para siempre. Aprendes a diseñar una base de datos, a consultarla con SQL y a conectarla con tu servidor en Python. Al terminar tienes una página web completa, hecha por ti desde cero.', 'Diseñar una base de datos en PostgreSQL y conectarla con una aplicación web.', ARRAY['Bases de datos y tablas: Qué es una base de datos, tablas, filas y columnas, tipos de datos', 'Consultas con SQL: INSERT, SELECT y WHERE, UPDATE y DELETE', 'Relaciones entre tablas: Llaves primarias y foráneas, JOIN, diseñar tablas relacionadas', 'Proyecto integrador: Conectar Python con PostgreSQL, guardar y mostrar datos, presentación final']::text[], '[{"titulo":"Bases de datos y tablas","temas":["Qué es una base de datos","Tablas, filas y columnas","Tipos de datos"],"temasTexto":"Qué es una base de datos, tablas, filas y columnas, tipos de datos","actividades":["Crear en PostgreSQL la tabla de productos de una tienda del barrio."],"evidencia":"Script SQL que crea la tabla."},{"titulo":"Consultas con SQL","temas":["INSERT","SELECT y WHERE","UPDATE y DELETE"],"temasTexto":"INSERT, SELECT y WHERE, UPDATE y DELETE","actividades":["Llenar la tabla y responder preguntas de la tienda con consultas SQL."],"evidencia":"Archivo con las consultas y sus resultados."},{"titulo":"Relaciones entre tablas","temas":["Llaves primarias y foráneas","JOIN","Diseñar tablas relacionadas"],"temasTexto":"Llaves primarias y foráneas, JOIN, diseñar tablas relacionadas","actividades":["Diseñar las tablas de clientes y pedidos y unirlas con JOIN."],"evidencia":"Diagrama de las tablas y consultas con JOIN."},{"titulo":"Proyecto integrador","temas":["Conectar Python con PostgreSQL","Guardar y mostrar datos","Presentación final"],"temasTexto":"Conectar Python con PostgreSQL, guardar y mostrar datos, presentación final","actividades":["Guardar en PostgreSQL los mensajes que llegan a tu servidor y mostrarlos en tu página."],"evidencia":"Tu página web completa funcionando y presentada al grupo."}]'::jsonb, '{"modalidad":"Clase presencial en Barranquilla: diseña las tablas en el tablero con el grupo, escribe las consultas en vivo y cierra con la presentación de los proyectos.","nota":"","reto":"Agrega una tabla nueva a tu proyecto y muestra sus datos en tu página.","preguntas":["¿Qué información necesita guardar tu página?","¿Cómo se relacionan tus tablas?","¿Qué pasa si borras un registro?"]}'::jsonb, 'Tu página web completa: la página (HTML, CSS y JavaScript), el servidor (Python) y los datos guardados en PostgreSQL.');
